CREATE TABLE teams(id BIGSERIAL PRIMARY KEY, name VARCHAR(50) UNIQUE NOT NULL, description VARCHAR(500) NOT NULL DEFAULT '', leader_id BIGINT);
CREATE TABLE users(id BIGSERIAL PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(50) NOT NULL, password TEXT NOT NULL, role VARCHAR(10) NOT NULL CHECK(role IN ('admin','member')), team_id BIGINT REFERENCES teams(id) DEFERRABLE INITIALLY DEFERRED, active INT NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
ALTER TABLE teams ADD CONSTRAINT team_leader_fk FOREIGN KEY(leader_id) REFERENCES users(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE sessions(token_hash VARCHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), expires DOUBLE PRECISION NOT NULL);
CREATE TABLE admin_invites(token_hash VARCHAR(64) PRIMARY KEY, creator_id BIGINT NOT NULL REFERENCES users(id), expires DOUBLE PRECISION NOT NULL, used_by BIGINT REFERENCES users(id));
CREATE TABLE rooms(id BIGSERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, capacity INT NOT NULL CHECK(capacity BETWEEN 1 AND 1000));
CREATE TABLE events(id BIGSERIAL PRIMARY KEY, title VARCHAR(100) NOT NULL, target_id BIGINT NOT NULL REFERENCES users(id), creator_id BIGINT NOT NULL REFERENCES users(id), start_at TIMESTAMPTZ NOT NULL, end_at TIMESTAMPTZ NOT NULL, location VARCHAR(100) NOT NULL DEFAULT '', room_id BIGINT REFERENCES rooms(id), notes TEXT NOT NULL DEFAULT '', status VARCHAR(12) NOT NULL CHECK(status IN ('pending','accepted','rejected','cancelled')), phase VARCHAR(16) NOT NULL DEFAULT 'not_started' CHECK(phase IN ('not_started','in_progress','completed')), source VARCHAR(10) NOT NULL DEFAULT 'manual', original_text TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(end_at>start_at));
CREATE TABLE event_details(event_id BIGINT PRIMARY KEY REFERENCES events(id), attrs JSONB NOT NULL DEFAULT '{}');
CREATE TABLE event_history(id BIGSERIAL PRIMARY KEY, event_id BIGINT NOT NULL REFERENCES events(id), actor_id BIGINT REFERENCES users(id), action VARCHAR(40) NOT NULL, snapshot JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications(id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), event_id BIGINT REFERENCES events(id), title VARCHAR(200) NOT NULL, body TEXT NOT NULL, is_read INT NOT NULL DEFAULT 0 CHECK(is_read IN (0,1)), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ai_drafts(id BIGSERIAL PRIMARY KEY, owner_id BIGINT REFERENCES users(id), result JSONB NOT NULL, complete INT NOT NULL, engine VARCHAR(16) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), sent_event_id BIGINT REFERENCES events(id), corrected INT NOT NULL DEFAULT 0);
CREATE TABLE event_requests(user_id BIGINT NOT NULL REFERENCES users(id), request_id VARCHAR(100) NOT NULL, payload_hash VARCHAR(64) NOT NULL, event_id BIGINT NOT NULL REFERENCES events(id), PRIMARY KEY(user_id,request_id));
CREATE TABLE audit(id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES users(id), action VARCHAR(100) NOT NULL, detail JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE migration_runs(source_digest VARCHAR(64) PRIMARY KEY, imported_at TIMESTAMPTZ NOT NULL DEFAULT now(), counts JSONB NOT NULL);
CREATE INDEX event_recipient_time ON events(target_id,start_at,end_at);
CREATE INDEX event_creator ON events(creator_id);
CREATE INDEX event_room_time ON events(room_id,start_at,end_at);
CREATE INDEX notification_inbox ON notifications(user_id,id DESC);
CREATE INDEX notification_unread ON notifications(user_id) WHERE is_read=0;
CREATE INDEX history_event ON event_history(event_id,id DESC);
CREATE INDEX session_user_idx ON sessions(user_id);
CREATE INDEX draft_owner ON ai_drafts(owner_id,id DESC);
INSERT INTO rooms(name,capacity) SELECT i||'号会议室',8+i*2 FROM generate_series(1,5) i;
